from solution import mask_digits

def test_mask_digits_with_numerical_data():
    assert mask_digits("My phone number is 123-456-7890, but don't call after 9 PM.") == "My phone number is ###-###-####, but don't call after # PM."

def test_mask_digits_with_no_numerical_data():
    assert mask_digits("There are no digits here!") == "There are no digits here!"

def test_mask_digits_with_all_digits():
    assert mask_digits("1234567890") == "##########"

def test_mask_digits_with_empty_string():
    assert mask_digits("") == ""

def test_mask_digits_with_mixed_characters():
    assert mask_digits("abc123def456ghi789") == "abc###def###ghi###"

