from solution import validateCommands

def test_empty_commands():
    transitions = {'A': {'0': 'B', '1': 'C'}, 'B': {'0': 'A', '1': 'D'}, 'C': {'0': 'D', '1': 'A'}, 'D': {'0': 'C', '1': 'B'}}
    start = 'A'
    final = ['D']
    assert validateCommands(transitions, start, final, "") == False

def test_single_command():
    transitions = {'A': {'0': 'B', '1': 'C'}, 'B': {'0': 'A', '1': 'D'}, 'C': {'0': 'D', '1': 'A'}, 'D': {'0': 'C', '1': 'B'}}
    start = 'A'
    final = ['D']
    assert validateCommands(transitions, start, final, "1") == False

def test_valid_multiple_commands():
    transitions = {'A': {'0': 'B', '1': 'C'}, 'B': {'0': 'A', '1': 'D'}, 'C': {'0': 'D', '1': 'A'}, 'D': {'0': 'C', '1': 'B'}}
    start = 'A'
    final = ['D']
    assert validateCommands(transitions, start, final, "01") == True  # A -> B -> D

def test_invalid_multiple_commands():
    transitions = {'A': {'0': 'B', '1': 'C'}, 'B': {'0': 'A', '1': 'D'}, 'C': {'0': 'D', '1': 'A'}, 'D': {'0': 'C', '1': 'B'}}
    start = 'A'
    final = ['D']
    assert validateCommands(transitions, start, final, "011") == False  # A -> B -> D -> B

def test_final_state_not_reached():
    transitions = {'A': {'0': 'B', '1': 'C'}, 'B': {'0': 'A', '1': 'D'}, 'C': {'0': 'D', '1': 'A'}, 'D': {'0': 'C', '1': 'B'}}
    start = 'A'
    final = ['D']
    assert validateCommands(transitions, start, final, "0") == False  # A -> B (not a final state)

