from solution import categorize_transactions

def test_categorize_transactions_basic():
    transactions = [
        {"id": 1, "amount": 100, "type": "debit"},
        {"id": 2, "amount": 200, "type": "credit"},
        {"id": 3, "amount": 50, "type": "debit"},
        {"id": 4, "amount": 350, "type": "credit"}
    ]
    expected_output = {
        "credit": [
            {"id": 2, "amount": 200, "type": "credit"},
            {"id": 4, "amount": 350, "type": "credit"}
        ],
        "debit": [
            {"id": 1, "amount": 100, "type": "debit"},
            {"id": 3, "amount": 50, "type": "debit"}
        ]
    }
    assert categorize_transactions(transactions) == expected_output

