from solution import prim_mst

def test_example_case():
    n = 5
    edges = {
        0: [(1, 2), (3, 6)],
        1: [(0, 2), (2, 3), (3, 8), (4, 5)],
        2: [(1, 3), (4, 7)],
        3: [(0, 6), (1, 8)],
        4: [(1, 5), (2, 7)]
    }
    assert prim_mst(n, edges) == 16

def test_single_node():
    n = 1
    edges = {
        0: []
    }
    assert prim_mst(n, edges) == 0

def test_two_connected_nodes():
    n = 2
    edges = {
        0: [(1, 1)],
        1: [(0, 1)]
    }
    assert prim_mst(n, edges) == 1

def test_line_graph():
    n = 4
    edges = {
        0: [(1, 1)],
        1: [(0, 1), (2, 1)],
        2: [(1, 1), (3, 1)],
        3: [(2, 1)]
    }
    assert prim_mst(n, edges) == 3

def test_cyclic_graph():
    n = 4
    edges = {
        0: [(1, 1), (2, 4)],
        1: [(0, 1), (2, 2), (3, 5)],
        2: [(0, 4), (1, 2), (3, 1)],
        3: [(1, 5), (2, 1)]
    }
    assert prim_mst(n, edges) == 4

