from solution import shortest_path

def test_shortest_path_basic():
    graph = {
        'A': ['B', 'C'],
        'B': ['A', 'D', 'E'],
        'C': ['A', 'F'],
        'D': ['B'],
        'E': ['B', 'F'],
        'F': ['C', 'E']
    }
    assert shortest_path(graph, 'A', 'F') in [['A', 'C', 'F'], ['A', 'B', 'E', 'F']]
    assert shortest_path(graph, 'A', 'D') == ['A', 'B', 'D']
    assert shortest_path(graph, 'B', 'F') == ['B', 'E', 'F']
    assert shortest_path(graph, 'D', 'E') == ['D', 'B', 'E']

def test_no_path():
    graph = {
        'A': ['B'],
        'B': ['A'],
        'C': ['D'],
        'D': ['C']
    }
    assert shortest_path(graph, 'A', 'D') == []
    assert shortest_path(graph, 'B', 'C') == []
    assert shortest_path(graph, 'A', 'C') == []

def test_single_node():
    graph = {
        'A': []
    }
    assert shortest_path(graph, 'A', 'A') == ['A']
    assert shortest_path(graph, 'A', 'B') == []

def test_disconnected_graph():
    graph = {
        'A': ['B'],
        'B': ['A'],
        'C': ['D'],
        'D': ['C']
    }
    assert shortest_path(graph, 'A', 'B') == ['A', 'B']
    assert shortest_path(graph, 'C', 'D') == ['C', 'D']
    assert shortest_path(graph, 'A', 'C') == []

def test_self_loop():
    graph = {
        'A': ['A']
    }
    assert shortest_path(graph, 'A', 'A') == ['A']

def test_large_graph():
