        0: [1, 2],
        1: [0, 3, 4],
        2: [0, 5, 6],
        3: [1],
        4: [1],
        5: [2],
        6: [2, 7],
        7: [6]
    }
    assert shortest_path(graph, 0, 7) == [0, 2, 6, 7]
    assert shortest_path(graph, 3, 6) == [3, 1, 0, 2, 6]
    assert shortest_path(graph, 0, 5) == [0, 2, 5]

